   double prev_Q1_Odd;
   double prev_Q1_Even;
   double prev_Q1_input_Odd;
   double prev_Q1_input_Even;
   double jI_Odd[3];
   double jI_Even[3];
   double jI;
   double prev_jI_Odd;
   double prev_jI_Even;
   double prev_jI_input_Odd;
   double prev_jI_input_Even;
   double jQ_Odd[3];
   double jQ_Even[3];
   double jQ;
   double prev_jQ_Odd;
   double prev_jQ_Even;
   double prev_jQ_input_Odd;
   double prev_jQ_input_Even;
   double Q2;
   double I2;
   double prevQ2;
   double prevI2;
   double Re;
   double Im;
   double I1ForOddPrev2;
   double I1ForOddPrev3;
   double I1ForEvenPrev2;
   double I1ForEvenPrev3;
   double rad2Deg;
   double constDeg2RadBy360;
   double todayValue;
   double smoothPeriod;
   double local_smoothPrice[50];
   double *smoothPrice = &local_smoothPrice[0];
   int smoothPrice_Idx;
   int maxIdx_smoothPrice;
   int idx;
   int DCPeriodInt;
   double DCPhase;
   double DCPeriod;
   double imagPart;
   double realPart;

   if( (startIdx < 0) || (startIdx > TA_INDEX_MAX) )
      return TA_OUT_OF_RANGE_START_INDEX;
   if( (endIdx < 0) || (endIdx > TA_INDEX_MAX) || (endIdx < startIdx) )
      return TA_OUT_OF_RANGE_END_INDEX;

   if( !inReal )
      return TA_BAD_PARAM;
   if( !outBegIdx || !outNBElement )
      return TA_BAD_PARAM;
   if( !outReal )
      return TA_BAD_PARAM;

   a = 0.0962;
   b = 0.5769;
   smoothPrice = &local_smoothPrice[0];
   maxIdx_smoothPrice = (int)(sizeof(local_smoothPrice)/sizeof(double))-1;
   smoothPrice_Idx = 0;
   tempReal = atan(1);
   rad2Deg = 45.0 / tempReal;
   constDeg2RadBy360 = tempReal * 8.0;
   lookbackTotal = TA_HT_DCPHASE_Lookback();
   if( startIdx < lookbackTotal )
   {
      startIdx = lookbackTotal;
   }
   if( startIdx > endIdx )
   {
      *outBegIdx= 0;
      *outNBElement= 0;
      return TA_SUCCESS;
   }
   *outBegIdx= startIdx;
   trailingWMAIdx = startIdx - lookbackTotal;
   today = trailingWMAIdx;
   tempReal = (double)inReal[today++];
   periodWMASub = tempReal;
   periodWMASum = tempReal;
   tempReal = (double)inReal[today++];
   periodWMASub += tempReal;
   periodWMASum += tempReal * 2.0;
   tempReal = (double)inReal[today++];
   periodWMASub += tempReal;
   periodWMASum += tempReal * 3.0;
   trailingWMAValue = 0.0;
   i = 34;
   do
   {
      tempReal = (double)inReal[today++];
      periodWMASub += tempReal;
      periodWMASub -= trailingWMAValue;
      periodWMASum += tempReal * 4.0;
      trailingWMAValue = (double)inReal[trailingWMAIdx++];
      smoothedValue = periodWMASum * 0.1;
      periodWMASum -= periodWMASub;
   } while( --i != 0 );
   hilbertIdx = 0;
   detrender_Odd[0] = 0.0;
   detrender_Odd[1] = 0.0;
   detrender_Odd[2] = 0.0;
   detrender_Even[0] = 0.0;
   detrender_Even[1] = 0.0;
   detrender_Even[2] = 0.0;
   detrender = 0.0;
   prev_detrender_Odd = 0.0;
   prev_detrender_Even = 0.0;
   prev_detrender_input_Odd = 0.0;
   prev_detrender_input_Even = 0.0;
   Q1_Odd[0] = 0.0;
   Q1_Odd[1] = 0.0;
   Q1_Odd[2] = 0.0;
   Q1_Even[0] = 0.0;
   Q1_Even[1] = 0.0;
