      if( retCode != TA_SUCCESS || outNbElement1 == 0 )
      {
         free(tempRSIBuffer);
         dummyBegIdx = 0;
         dummyNBElement = 0;
         TA_RSI_Close( sub0 ); TA_STOCHF_Close( sub1 ); if( !outStride ) TA_Free( sc_outFastK ); if( !outStride ) TA_Free( sc_outFastD );
         return retCode;
      }
      /* Sub-stream 1: stochf over `tempRSIBuffer, tempRSIBuffer, tempRSIBuffer`, warmed from bar 0 up to the
       * sub-call's own startIdx (the seeding point). */
      {
         subRc = TA_STOCHF_OpenAndFillInternal( &sub1, tempRSIBuffer, tempRSIBuffer, tempRSIBuffer, (0), (tempArraySize - 1) + 1, optInFastK_Period, optInFastD_Period, optInFastD_MAType, &outBegIdx2, &dummyNBElement, sc_outFastK, sc_outFastD );
         if( subRc != TA_SUCCESS )
         {
            free(tempRSIBuffer);
            TA_RSI_Close( sub0 ); TA_STOCHF_Close( sub1 ); if( !outStride ) TA_Free( sc_outFastK ); if( !outStride ) TA_Free( sc_outFastD );
            return subRc;
         }
      }
      retCode = subRc;
      free(tempRSIBuffer);
      if( retCode != TA_SUCCESS || (int)dummyNBElement == 0 )
      {
         dummyBegIdx = 0;
         dummyNBElement = 0;
         TA_RSI_Close( sub0 ); TA_STOCHF_Close( sub1 ); if( !outStride ) TA_Free( sc_outFastK ); if( !outStride ) TA_Free( sc_outFastD );
         return retCode;
      }

      /* Capture the live producer state + sub handles. */
      if( dummyNBElement < 1 ) { *outBegIdx = 0; *outNBElement = 0; TA_RSI_Close( sub0 ); TA_STOCHF_Close( sub1 ); if( !outStride ) TA_Free( sc_outFastK ); if( !outStride ) TA_Free( sc_outFastD ); return TA_INSUFFICIENT_HISTORY; }
      sp = (struct TA_STOCHRSI_Stream *)TA_Malloc( sizeof(*sp) );
      if( !sp ) { TA_RSI_Close( sub0 ); TA_STOCHF_Close( sub1 ); if( !outStride ) TA_Free( sc_outFastK ); if( !outStride ) TA_Free( sc_outFastD ); return TA_ALLOC_ERR; }
      memset( sp, 0, sizeof(*sp) );
      sp->optInTimePeriod = optInTimePeriod;
      sp->optInFastK_Period = optInFastK_Period;
      sp->optInFastD_Period = optInFastD_Period;
      sp->optInFastD_MAType = optInFastD_MAType;
      sp->sub0 = sub0;
      sp->sub1 = sub1;
      *outBegIdx = dummyBegIdx;
      *outNBElement = dummyNBElement;
      if( !outStride ) outFastK[0] = sc_outFastK[dummyNBElement - 1];
      if( !outStride ) outFastD[0] = sc_outFastD[dummyNBElement - 1];
      if( !outStride ) TA_Free( sc_outFastK );
      if( !outStride ) TA_Free( sc_outFastD );
